        float ripple = sin(uv.y * 260.0 + uTime * PI * 16.0) * 0.003;
        vec4 b = building(vec2(uv.x + ripple, ground + (ground - uv.y) * 1.2));
        col = mix(vec3(0.01, 0.01, 0.025), b.rgb * 0.4, b.a);
