        float fd = fract(a * segs);
        float dash = smoothstep(0.08, 0.18, fd) * (1.0 - smoothstep(0.72, 0.82, fd));
        float ring = smoothstep(0.12, 0.28, fr) * (1.0 - smoothstep(0.68, 0.84, fr));
