    col += mix(colorAt(0.05 + uPhase * 0.5), vec3(1.0), 0.5) * spec * spec * 0.9;
    col += colorAt(0.33) * length(g) * 0.08;
    col *= clamp(1.3 - 0.25 * length(p), 0.0, 1.0);
    return col;
}

