        float across = vertical ? abs(fract(w.x + 0.5) - 0.5) : abs(fract(w.y + 0.5) - 0.5);
        float along = vertical ? w.y : w.x;
        float side = (vertical ? fract(w.x + 0.5) : fract(w.y + 0.5)) < 0.5 ? 1.0 : -1.0;
        // Streetlights along the kerbs.
